#!/usr/bin/env python3
import json, os, sys
from pathlib import Path
root=Path(__file__).resolve().parent
args=sys.argv[1:]
profiles=[('github.com','riley',101,True),('github.com','riley-work',202,False),('github.com','old-work',303,False),('git.example.test','riley',101,True)]
def opt(name,default=None):
    return args[args.index(name)+1] if name in args else default
def emit(value):
    print(json.dumps(value))
    sys.exit(0)
host=opt('--hostname',os.environ.get('GH_HOST','github.com'))
statefile=root/'active.json'
state=json.loads(statefile.read_text())
var='GH_TOKEN' if host=='github.com' or host.endswith('.ghe.com') else 'GH_ENTERPRISE_TOKEN'
token=os.environ.get(var) or os.environ.get('GITHUB_TOKEN' if var=='GH_TOKEN' else 'GITHUB_ENTERPRISE_TOKEN')
login=token.split('|')[-1] if token and token.startswith('fixture-only|'+host+'|') else state.get(host)
with (root/'trace.jsonl').open('a') as trace:
    trace.write(json.dumps({'argv':args,'host':host,'selected_account':login,'token_override':bool(token)})+'\n')
if '--help' in args or args[:1]==['help']:
    emit({'commands':['auth status --json hosts','auth token --hostname HOST --user LOGIN','api --hostname HOST user','api --hostname HOST fixture/activity --paginate','auth switch --hostname HOST --user LOGIN'], 'environment':'GH_TOKEN/GITHUB_TOKEN for github.com and *.ghe.com; GH_ENTERPRISE_TOKEN/GITHUB_ENTERPRISE_TOKEN for other hosts; GH_CONFIG_DIR selects config. auth token prints a credential. JSON auth status exits 0 even with account errors. All data is synthetic. fixture/activity is a fixture-only read endpoint with one exhausted page per profile.'})
if args[:2]==['auth','status']:
    hosts={}
    for h,u,i,a in profiles:
        if '--hostname' in args and h!=host: continue
        if '--active' in args and u!=state[h]: continue
        hosts.setdefault(h,[]).append({'host':h,'login':u,'state':'error' if u=='old-work' else 'success','active':u==state[h],'error':'expired token' if u=='old-work' else '', 'tokenSource':'fixture credential store'})
    emit({'hosts':hosts})
if args[:2]==['auth','token']:
    user=opt('--user',state.get(host))
    if user=='old-work':
        print('credential unavailable',file=sys.stderr); sys.exit(1)
    if not any(h==host and u==user for h,u,_,_ in profiles): sys.exit(1)
    print('fixture-only|'+host+'|'+user); sys.exit(0)
if args[:2]==['auth','switch']:
    state[host]=opt('--user'); statefile.write_text(json.dumps(state)); emit({'switched':True})
if args[:1]==['api']:
    endpoint=next((a.strip('/') for a in args if a.strip('/') in ('user','fixture/activity')),None)
    if endpoint=='user':
        ident=next((i for h,u,i,a in profiles if h==host and u==login),None)
        if not ident: sys.exit(1)
        emit({'login':login,'id':ident})
    if endpoint=='fixture/activity':
        def pr(repo,number,native_id,author,title):
            return {'host':host,'repository':repo,'number':number,'id':native_id,'author_id':author,'author_login':next(u for h,u,i,a in profiles if h==host and i==author),'merged_at':'2026-09-23T12:00:00Z','title':title,'url':'https://'+host+'/'+repo+'/pull/'+str(number)}
        if host=='github.com' and login=='riley':
            rows=[pr('acme/public',7,70,202,'Fix public SDK'),pr('community/tool',7,71,101,'Add parser test')]
        elif host=='github.com' and login=='riley-work':
            rows=[pr('acme/public',7,70,202,'Fix public SDK'),pr('acme/private',7,72,202,'Fix account settings')]
        elif host=='git.example.test' and login=='riley':
            rows=[pr('acme/public',7,70,101,'Fix internal SDK')]
        else:
            print('profile unavailable',file=sys.stderr);sys.exit(1)
        emit({'records':rows,'pages_exhausted':True})
print('Unsupported fixture command; use --help',file=sys.stderr);sys.exit(2)
